/**
 *
 * MenuArrow is a component that displays an arrow pointing to the anchor element.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuArrow
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuRootInstance } from './MenuRoot.types';
/**
 * Defines passthrough(pt) options type in MenuArrow component.
 */
export type MenuArrowPassThroughType<E> = PassThroughType<MenuArrowInstance, E>;
/**
 * Defines passthrough(pt) options of MenuArrow component.
 */
export interface MenuArrowPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuArrowPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in MenuArrow component.
 */
export interface MenuArrowProps extends BaseComponentProps<MenuArrowInstance, unknown, MenuArrowPassThrough> {
}
/**
 * Defines valid state in MenuArrow component.
 */
export interface MenuArrowState {
}
/**
 * Defines the methods and properties exposed by MenuArrow component.
 */
export interface MenuArrowExposes {
    /**
     * The Menu component instance.
     */
    menu: MenuRootInstance | undefined | null;
}
/**
 * Instance of MenuArrow component.
 */
export type MenuArrowInstance = ComponentInstance<MenuArrowProps, MenuArrowState, MenuArrowExposes>;
